// Optional orientation. No AI calls, playback changes, or automatic popup.
(()=>{
 const steps=[
  {title:'Start with the play.',tag:'01 / WATCH',text:'Open Watch and press play. The crew explains the moment from five perspectives. You can follow along even if you’re new to football.',details:[['Watch','Follow the film or the synthetic match, then ask the crew a question.'],['Your experience','Choose a language, a beginner explanation, or a more tactical perspective.']],route:'watch',cta:'Open Watch'},
  {title:'Make the game make sense.',tag:'02 / UNDERSTAND',text:'Match Centre connects the players, passes and numbers. Match Lab lets you explore the synthetic scenarios and analytical tools.',details:[['Match Centre','Select a player or replay a moment to see the evidence behind the explanation.'],['Inside the play','Choose “Show me why,” learn a football concept, or inspect the pass calculation.']],route:'centre',cta:'Open Match Centre'},
  {title:'Put the story to the test.',tag:'03 / CHALLENGE',text:'Truth Lab is where you challenge an explanation. Change the evidence and see which claims must change with it.',details:[['Truth Lab','Compare original and corrected tracking. Keep the recorded events separate from interpretations.'],['Meet your AI crew','Explore each presenter’s role, expertise and instructions in Presenters.']],route:'truth',cta:'Open Truth Lab'}
 ];
 let step=0,opener=null;
 const dialog=document.createElement('dialog');dialog.className='welcome-guide';dialog.setAttribute('aria-labelledby','welcome-guide-title');
 dialog.innerHTML='<header><span>BTR / QUICK START</span><button type="button" aria-label="Close quick start">×</button></header><nav aria-label="Quick start steps"></nav><section><small id="guide-tag"></small><h2 id="welcome-guide-title"></h2><p id="guide-intro"></p><div id="guide-details"></div></section><footer><button type="button" id="guide-back">Back</button><span id="guide-count"></span><button type="button" id="guide-next">Next →</button></footer><button type="button" id="guide-open"></button><p class="guide-note">Explore at your pace. This guide doesn’t use AI credits.</p>';
 document.body.append(dialog);const q=s=>dialog.querySelector(s),nav=q('nav');
 const visual=document.createElement('div');visual.className='guide-visual';q('section').prepend(visual);
 const scenes=[
  '<img class="guide-scene" src="assets/pitchside-minute-clean-poster.jpg" alt="Illustrative generated football scene"><span class="guide-scene-label">YOUR FRONT ROW</span><div class="guide-scene-title">THE PLAY.<br>EVERY PERSPECTIVE.</div><div class="guide-voices">'+['scout','guide','vector','check','host'].map(n=>'<img src="assets/'+n+'-portrait.webp" alt="'+n+'">').join('')+'</div><span class="guide-scene-foot">FIVE VOICES · ONE WATCH PARTY</span>',
  '<span class="guide-scene-label">SEE THE CONNECTIONS</span><svg class="guide-pitch" viewBox="0 0 240 190" role="img" aria-label="Illustrative pass diagram"><rect x="10" y="10" width="220" height="170" rx="3"/><path d="M120 10V180M10 55H45V135H10M230 55H195V135H230"/><circle cx="120" cy="95" r="26"/><path class="guide-pass" d="M57 132L104 100L165 117L193 52"/><g class="guide-dots"><circle cx="57" cy="132" r="5"/><circle cx="104" cy="100" r="5"/><circle cx="165" cy="117" r="5"/><circle cx="193" cy="52" r="5"/></g></svg><div class="guide-example"><small>THE QUESTION BEHIND THE NUMBER</small><strong>What did that pass change?</strong><span>Follow the player. Inspect the event.</span></div><span class="guide-scene-foot">ILLUSTRATIVE DIAGRAM</span>',
  '<span class="guide-scene-label">FOLLOW THE EVIDENCE</span><div class="guide-evidence"><div><small>ORIGINAL READING</small><p>The defender moved wide.</p></div><span class="guide-revise">↓ &nbsp; TRACKING CORRECTED</span><div><small>REVISED READING</small><strong>That movement claim<br>must be withdrawn.</strong></div></div><div class="guide-verdict"><img src="assets/check-portrait.webp" alt="Check, evidence editor"><span><strong>CHECK / EVIDENCE EDITOR</strong>Change the source.<br>Recheck the story.</span></div><span class="guide-scene-foot">AN EXAMPLE FROM TRUTH LAB</span>'
 ];
 steps.forEach((s,i)=>{const b=document.createElement('button');b.type='button';b.textContent=['Watch','Understand','Challenge'][i];b.onclick=()=>{step=i;render();};nav.append(b);});
 function render(){const s=steps[step];dialog.dataset.step=step;visual.innerHTML=scenes[step];q('#guide-tag').textContent=s.tag;q('h2').textContent=s.title;q('#guide-intro').textContent=s.text;q('#guide-details').replaceChildren();for(const[title,text]of s.details){const article=document.createElement('article'),strong=document.createElement('strong'),p=document.createElement('p');strong.textContent=title;p.textContent=text;article.append(strong,p);q('#guide-details').append(article);}nav.querySelectorAll('button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===step)));q('#guide-back').disabled=step===0;q('#guide-next').textContent=step===2?'Done':'Next →';q('#guide-count').textContent=`${step+1} of 3`;q('#guide-open').textContent=s.cta+' ↗';}
 function close(){dialog.close();if(opener?.isConnected)opener.focus();}
 q('header button').onclick=close;q('#guide-back').onclick=()=>{step=Math.max(0,step-1);render();};q('#guide-next').onclick=()=>{if(step===2)close();else{step++;render();}};
 q('#guide-open').onclick=()=>{const route=steps[step].route;dialog.close();location.hash=route;const splash=document.querySelector('.btr-splash[open]');splash?.querySelector('.btr-enter')?.click();if(!splash)document.getElementById(route+'-nav')?.focus();};
 dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 document.addEventListener('btr-open-guide',()=>{opener=document.activeElement;step=0;render();if(!dialog.open)dialog.showModal();});
 const help=document.createElement('button');help.type='button';help.className='quick-start-help';help.textContent='?';help.setAttribute('aria-label','Open quick start guide');help.title='Quick start guide';help.onclick=()=>document.dispatchEvent(new Event('btr-open-guide'));document.querySelector('.header-end')?.append(help);
})();
